<?php require '../includes/bootstrap.php';admin_required();if($_SERVER['REQUEST_METHOD']==='POST'){$pdo->prepare('INSERT INTO problem_statements(event_id,problem_code,title,description,domain,difficulty,technology,max_teams,status) VALUES(?,?,?,?,?,?,?,?,?)')->execute([(int)$_POST['event_id'],trim($_POST['problem_code']),trim($_POST['title']),trim($_POST['description']),trim($_POST['domain']),$_POST['difficulty'],trim($_POST['technology']),max(1,(int)$_POST['max_teams']),$_POST['status']]);flash('success','Problem statement created.');redirect('problems.php');}$events=$pdo->query('SELECT event_id,event_name FROM events ORDER BY start_date DESC')->fetchAll();$rows=$pdo->query('SELECT p.*,e.event_name FROM problem_statements p JOIN events e ON e.event_id=p.event_id ORDER BY p.created_at DESC')->fetchAll();$title='Manage Problems';$base='../';$nav='<a href="dashboard.php">Dashboard</a><a href="events.php">Events</a><a href="selections.php">Selections</a><a href="../logout.php">Logout</a>';include '../includes/header.php';?><h1>Manage Problem Statements</h1><div class="card"><form method="post"><div class="grid"><div><label>Event</label><select name="event_id"><?php foreach($events as $e):?><option value="<?=e($e['event_id'])?>"><?=e($e['event_name'])?></option><?php endforeach;?></select></div><div><label>Code</label><input name="problem_code" required></div><div><label>Domain</label><input name="domain" required></div><div><label>Title</label><input name="title" required></div><div><label>Difficulty</label><select name="difficulty"><option>BEGINNER</option><option selected>INTERMEDIATE</option><option>ADVANCED</option></select></div><div><label>Technology</label><input name="technology"></div><div><label>Max Teams</label><input type="number" min="1" name="max_teams" value="10"></div><div><label>Status</label><select name="status"><option>AVAILABLE</option><option>FULL</option><option>CLOSED</option></select></div></div><label>Description</label><textarea name="description" required></textarea><button class="btn">Add Problem</button></form></div><div class="card"><table class="table"><tr><th>Code</th><th>Title</th><th>Event</th><th>Domain</th><th>Status</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['problem_code'])?></td><td><?=e($r['title'])?></td><td><?=e($r['event_name'])?></td><td><?=e($r['domain'])?></td><td><span class="badge"><?=e($r['status'])?></span></td></tr><?php endforeach;?></table></div><?php include '../includes/footer.php';?>
